pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 n0, uint64 t0, uint256 b0, bytes32 h0, uint64 s0, bytes32 bh0, uint256 o0, uint256 sc0) internal {
        uint64 numberBefore;
        try c.number() returns (uint64 __r) { numberBefore = __r; } catch { return; }
        uint64 timestampBefore;
        try c.timestamp() returns (uint64 __r) { timestampBefore = __r; } catch { return; }
        uint256 basefeeBefore;
        try c.basefee() returns (uint256 __r) { basefeeBefore = __r; } catch { return; }
        bytes32 hashBefore;
        try c.hash() returns (bytes32 __r) { hashBefore = __r; } catch { return; }
        uint64 seqBefore;
        try c.sequenceNumber() returns (uint64 __r) { seqBefore = __r; } catch { return; }
        bytes32 batcherBefore;
        try c.batcherHash() returns (bytes32 __r) { batcherBefore = __r; } catch { return; }
        uint256 overheadBefore;
        try c.l1FeeOverhead() returns (uint256 __r) { overheadBefore = __r; } catch { return; }
        uint256 scalarBefore;
        try c.l1FeeScalar() returns (uint256 __r) { scalarBefore = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(n0, t0, b0, h0, s0, bh0, o0, sc0) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue((!reverted) || (
                c.number() == numberBefore &&
                c.timestamp() == timestampBefore &&
                c.basefee() == basefeeBefore &&
                c.hash() == hashBefore &&
                c.sequenceNumber() == seqBefore &&
                c.batcherHash() == batcherBefore &&
                c.l1FeeOverhead() == overheadBefore &&
                c.l1FeeScalar() == scalarBefore
            ));
    }

    function testFuzz_run(uint64 n0, uint64 t0, uint256 b0, bytes32 h0, uint64 s0, bytes32 bh0, uint256 o0, uint256 sc0) public {
        _run(n0, t0, b0, h0, s0, bh0, o0, sc0);
    }

    receive() external payable {}
}
